pub fn outdated(ctx: Command.Context, original_cwd: []const u8, manager: *PackageManager) !void {
        const load_lockfile_result = manager.lockfile.loadFromCwd(manager, manager.allocator, manager.log, true);
        manager.lockfile = (switch (load_lockfile_result) {
.not_found => {
{
            if ((manager.options.log_level != .silent)) {
                _ = Output.errGeneric("missing lockfile, nothing outdated", .{});
            }
            _ = Global.crash();
        }
},
.err => |cause| {
{
            if ((manager.options.log_level != .silent)) {
                switch (cause.step) {
.open_file => {
_ = Output.errGeneric("failed to open lockfile: {s}", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
.parse_file => {
_ = Output.errGeneric("failed to parse lockfile: {s}", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
.read_file => {
_ = Output.errGeneric("failed to read lockfile: {s}", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
.migrating => {
_ = Output.errGeneric("failed to migrate lockfile: {s}", .{ @errorName((if (@typeInfo(@TypeOf(cause)) == .@"enum") @intFromEnum(cause) else cause.value)) });
},
}
                if (ctx.log.hasErrors()) {
                    _ = try manager.log.print(Output.errorWriter());
                }
            }
            _ = Global.crash();
        }
},
.ok => |ok| ok.lockfile,
});
        if (Output.enable_ansi_colors_stdout) {
            _ = try outdatedWithColor(manager, original_cwd, true);
        } else {
            _ = try outdatedWithColor(manager, original_cwd, false);
        }
}

pub fn outdatedWithColor(manager: *PackageManager, original_cwd: []const u8, comptime enable_ansi_colors: bool) !void {
        if ((manager.options.filter_patterns.len > 0)) {
            const filters = manager.options.filter_patterns;
            const workspace_pkg_ids = (blk_catch_2: { break :blk_catch_2 ((findMatchingWorkspaces(bun.default_allocator, original_cwd, manager, filters)) catch |e| { _ = &e; break :blk_catch_2 @as([]const PackageID, bun.handleOom(e)); }); });
            defer {
            _ = bun.default_allocator.free(workspace_pkg_ids);
            }
            _ = try manager.populateManifestCache(.{ .ids = workspace_pkg_ids });
            _ = try printOutdatedInfoTable(manager, workspace_pkg_ids, true, enable_ansi_colors);
        } else {
            if (manager.options.do.recursive) {
                const all_workspaces = bun.handleOom(getAllWorkspaces(bun.default_allocator, manager));
                defer {
                _ = bun.default_allocator.free(all_workspaces);
                }
                _ = try manager.populateManifestCache(.{ .ids = all_workspaces });
                _ = try printOutdatedInfoTable(manager, all_workspaces, true, enable_ansi_colors);
            } else {
                const root_pkg_id = manager.root_package_id.get(manager.lockfile, manager.workspace_name_hash);
                if ((root_pkg_id == invalid_package_id)) {
                    return;
                }
                const root_arr = .{ root_pkg_id };
                const root_slice = root_arr[0..1];
                _ = try manager.populateManifestCache(.{ .ids = root_slice });
                _ = try printOutdatedInfoTable(manager, root_slice, false, enable_ansi_colors);
            }
        }
}
